const input = $input.first().json;
const body = input.body || input;

const platforms = body.platforms || ['linkedin'];
const content = body.content || '';
const mediaUrl = body.media_url || null;

// Platform-specific formatting
const posts = [];

for (const platform of platforms) {
  let formattedContent = content;
  let maxLength = 3000;

  switch (platform) {
    case 'twitter':
      maxLength = 280;
      formattedContent = content.substring(0, 277) + (content.length > 277 ? '...' : '');
      break;
    case 'linkedin':
      maxLength = 3000;
      // Add hashtags at the end for LinkedIn
      if (body.hashtags?.length) {
        formattedContent += '\n\n' + body.hashtags.map(h => `#${h}`).join(' ');
      }
      break;
    case 'instagram':
      maxLength = 2200;
      if (body.hashtags?.length) {
        formattedContent += '\n\n' + body.hashtags.map(h => `#${h}`).join(' ');
      }
      break;
    case 'facebook':
      maxLength = 63206;
      break;
  }

  posts.push({
    json: {
      platform: platform,
      content: formattedContent.substring(0, maxLength),
      media_url: mediaUrl,
      link_url: body.link_url || null,
      client_id: body.client_id,
      campaign_id: body.campaign_id || null,
      scheduled_at: body.scheduled_at || new Date().toISOString()
    }
  });
}

return posts;

const results = $input.all();
const postData = $node['Format Per Platform'].json;

const postResult = results[0]?.json || {};
const success = !postResult.error && postResult.statusCode !== 401;

return [{
  json: {
    platform: postData.platform,
    success: success,
    post_id: postResult.id || postResult.data?.id || null,
    client_id: postData.client_id,
    content_preview: postData.content.substring(0, 100),
    posted_at: new Date().toISOString(),
    error: success ? null : (postResult.message || postResult.error || 'Unknown error')
  }
}];
